// 1. Recupero dati dai nodi precedenti
const elements = $json.elements || [];
const page = $json.page || 0;
const projectName = $json.projectName || "Progetto";

// 2. Dimensioni di riferimento (Layout Unstructured)
const L_WIDTH = 2885;
const L_HEIGHT = 3754;
const TOTAL_AREA = L_WIDTH * L_HEIGHT;

let images = [];
let totalImagesArea = 0;

// 3. Estrazione e calcolo area delle immagini
const rawImages = elements
  .filter(el => el.type === "Figure" || el.type === "Image")
  .map(el => {
    const coords = el.boundingBox || el.metadata?.coordinates || el.coordinates;
    const points = coords?.points;

    if (!points || points.length < 4) return null;

    const xs = points.map(p => p[0]);
    const ys = points.map(p => p[1]);

    const xMin = Math.min(...xs);
    const yMin = Math.min(...ys);
    const width = Math.max(...xs) - xMin;
    const height = Math.max(...ys) - yMin;

    totalImagesArea += (width * height);

    return {
      left: xMin,
      top: yMin,
      width: width,
      height: height,
      layout_width: coords.layout_width || L_WIDTH,
      layout_height: coords.layout_height || L_HEIGHT
    };
  })
  .filter(i => i !== null);

// 4. Calcolo percentuale di copertura
const coveragePercent = (totalImagesArea / TOTAL_AREA) * 100;

// 5. Decisione Strategia: Full Page vs Ritagli Singoli
const isFullPage = (page === 1 || coveragePercent > 80);

if (isFullPage) {
  // Caso Copertina o Mappa Gigante
  images.push({
    page: page,
    projectName: projectName,
    index: 1,
    type: "FullPage",
    fileName: `img_pag_${page}_full.png`,
    crop: {
      left: 0,
      top: 0,
      width: L_WIDTH,
      height: L_HEIGHT,
      layout_width: L_WIDTH,
      layout_height: L_HEIGHT
    }
  });
} else {
  // Caso immagini multiple nella pagina
  images = rawImages.map((img, idx) => ({
    page: page,
    projectName: projectName,
    index: idx + 1,
    type: "Image",
    fileName: `img_pag_${page}_${idx + 1}.png`,
    crop: img
  }));
}

// 6. Preparazione Testo per Groq (con segnaposti)
let markdownConSegnaposti = $json.markdown || "";

// Aggiungiamo i riferimenti alle immagini in fondo al testo affinché Groq li veda
if (images.length > 0) {
  const imageRefs = images.map(i => `[SEGNAPOSTO_IMMAGINE: ${i.fileName}]`).join("\n");
  markdownConSegnaposti += `\n\n--- RIFERIMENTI IMMAGINI ---\n${imageRefs}`;
}

// 7. Output Finale
return {
  projectName,
  page,
  pageType: isFullPage ? "full_image" : "standard",
  coverage: coveragePercent.toFixed(2) + "%",
  markdown: markdownConSegnaposti,
  images: images, // Questo array andrà nello Split Out
  hasImages: images.length > 0
};

