const REPLACEMENTS = {
  "N©ATT": "N° ATT.",
  "EFIfi": "Elfi",
  "TS UN": "TS U",
  "erriero": "guerriero",
  "dii rosso": "di rosso",
  "@apelli": "capelli",
  "ritor- neranno": "ritorneranno",
  "oDUNGEONS": "DUNGEONS",
  "GoDRAGONS": "DRAGONS",
  "DUNGEONS GoDRAGONS": "DUNGEONS & DRAGONS",
  "DUNGEONS &DRAGONS": "DUNGEONS & DRAGONS",
  "DUNGEONS&DRAGONS": "DUNGEONS & DRAGONS",
  "registratò": "registrato",
