const fs = require('fs');
function applySolution(content, found, sol) {
  const before = sol.before || 0;
  const after = sol.after || 0;
  if (!before && !after) {
    return content.split(found).join(sol.correct);
  }
  let result = '';
  let searchFrom = 0;
  let idx = content.indexOf(found, searchFrom);
  while (idx !== -1) {
    const start = Math.max(0, idx - before);
    const end = idx + found.length + after;
    result += content.slice(searchFrom, start) + sol.correct;
    searchFrom = end;
    idx = content.indexOf(found, searchFrom);
  }
  result += content.slice(searchFrom);
  return result;
}

