const fs = require('fs');
const item = $input.item;
let markdown = item.json.markdown || '';
const pageNum = item.json.page || 0;
const projectName = item.json.projectName || '';
const errorsPath = `/shared/projects/qa/errors/${projectName}.json`;
const errors = [];

// 0. Rimozione boilerplate editoriale
const BOILERPLATE_PATTERNS = [
  /^[\s:;\-–—"']*Stampato in Italia[\s.]*$/i,
  /^[\s:;\-–—"']*©\s*\d{4}(?:[,;]\s*\d{4})*\s*TSR,?\s*Inc\.?\s*(?:Tutti i diritti riservati\.?)?[\s.]*$/i,
  /^[\s:;\-–—"']*Tutti i diritti riservati\.?[\s.]*$/i,
  /^[\s:;\-–—"']*TSR,?\s*Inc\.?\s*(?:P\.?O\.?\s*Box[^\n]*)?[\s.]*$/i,
  /^[\s:;\-–—"']*EDITRICE GIOCHI[\s.]*$/i,
  /^\s*[-–—_]{1,5}\s*$/,
];
markdown = markdown.split('\n').map(line => {
  const t = line.trim();
  if (t.length === 0 || t.length > 100) return line;
  return BOILERPLATE_PATTERNS.some(re => re.test(t)) ? '' : line;
}).join('\n');
item.json.markdown = markdown;

// 0b. Fix notazione dadi fusa
markdown = markdown
  .replace(/\b([1-9])(10|12|20|2|3|4|6|8)([+-]\d+)?\s+(ferite?|danni?)/gi,
    (m, count, faces, bonus, unit) => `${count}d${faces}${bonus || ''} ${unit}`)
  .replace(/\b([1-9])(10|12|20|2|3|4|6|8)([+-]\d+)?\s+(punti\s+ferita|punti\s+danno)/gi,
    (m, count, faces, bonus, unit) => `${count}d${faces}${bonus || ''} ${unit}`);
item.json.markdown = markdown;

// 1. Heading sospetto
const cleanForCompare = (s) => s.toLowerCase().replace(/[®™°"''".,;:!?()]/g, '').replace(/\s+/g, ' ').trim();
const lines = markdown.split('\n');
for (let i = 0; i < lines.length; i++) {
  const headingMatch = lines[i].match(/^#{1,6}\s+(.+)$/);
  if (!headingMatch) continue;
  const headingText = cleanForCompare(headingMatch[1]);
  if (headingText.length < 4) continue;
  let prev = '';
  for (let j = i - 1; j >= 0; j--) {
    const t = lines[j].trim();
    if (!t) continue;
    if (/^#{1,6}\s+/.test(t)) continue;
    prev = lines[j]; break;
  }
  const prevClean = cleanForCompare(prev);
  if (prevClean && prevClean.endsWith(headingText)) {
    errors.push({ page: pageNum, type: 'suspicious_heading', found: headingMatch[1].trim(), context: prev.substring(Math.max(0, prev.length - 100)) });
  }
}

// 2. Garbage celle tabella
const rowRegex = /<tr>([\s\S]*?)<\/tr>/gi;
let rowMatch;
while ((rowMatch = rowRegex.exec(markdown)) !== null) {
  const row = rowMatch[1];
  const cells = [];
  const cellRegex = /<td>([^<]*)<\/td>/g;
  let cm;
  while ((cm = cellRegex.exec(row)) !== null) cells.push(cm[1].trim());
  cells.forEach((cell, idx) => {
    if (!cell || cell.length < 2) return;
    if (/^[\d\s]+$/.test(cell)) return;
    const letters = (cell.match(/[a-zA-ZÀ-ÿ ]/g) || []).length;
    const ratio = letters / cell.length;
    const hasSymbols = /[0-9\(\)\[\]{}\\\/~^|]/.test(cell);
    if (ratio < 0.4 && hasSymbols) {
      errors.push({ page: pageNum, type: 'table_garbage', context: cells.filter((c,i)=>i!==idx&&c).join(' | ').substring(0,80), column_index: idx, found: cell });
    }
  });
}

// 3. Lingua straniera
const ptWords = /\b(também|baixo|quartos|falar|beber|então|muito|todos)\b/i;
const esWords = /\b(también|están|tienen|pueden|pero)\b/i;
const ptMatch = markdown.match(ptWords);
const esMatch = markdown.match(esWords);
if (ptMatch || esMatch) {
  errors.push({ page: pageNum, type: 'wrong_language', language: ptMatch ? 'portuguese' : 'spanish', found: (ptMatch || esMatch)[0] });
}

// 4. Parola sospetta per bug font l/1 (es. "m1ss10ne" invece di "missione").
// Stesso bug di font gia' visto per dadi e codici area (vedi estrai-pagine-pdf),
// applicato qui a parole normali - non essendoci un insieme finito di valori
// validi da controllare, non e' auto-correggibile con una regex: si segnala
// come errore QA cosi' passa per il meccanismo esistente solutions.json.
// Segnale: cifra 0/1 incastrata in una parola (lettera-cifra-lettera), oppure
// cifra finale preceduta da almeno 4 lettere - i dadi ("d20","3d6") hanno
// sempre un prefisso di 1-2 caratteri, mai piu' lungo, quindi restano esclusi
// senza doverli conoscere esplicitamente. Cifre 2-9 escluse (fuori scope).
const DICE_TOKEN_RE = /^\d{1,2}[dD]\d{1,3}([+-]\d+)?$/;
const suspectWordTokens = markdown.match(/\b[a-zA-Z\u00e0\u00e8\u00e9\u00ec\u00f2\u00f9\u00c0\u00c8\u00c9\u00cc\u00d2\u00d90-9]+\b/g) || [];
const seenSuspect = new Set();
for (const tok of suspectWordTokens) {
  if (/[2-9]/.test(tok)) continue;
  if (!/[a-zA-Z\u00e0-\u00fc]/i.test(tok) || !/[01]/.test(tok)) continue;
  if (DICE_TOKEN_RE.test(tok)) continue;
  const hasInternalTransition = /[01][a-zA-Z\u00e0-\u00fc]/i.test(tok);
  const hasTrailingDigit = /^[a-zA-Z\u00e0-\u00fc]{4,}[01]+$/i.test(tok);
  if (!hasInternalTransition && !hasTrailingDigit) continue;
  if (seenSuspect.has(tok)) continue;
  seenSuspect.add(tok);
  const idx = markdown.indexOf(tok);
  const context = markdown.substring(Math.max(0, idx - 40), idx + tok.length + 40);
  errors.push({ page: pageNum, type: 'suspect_word', found: tok, context });
}

if (errors.length > 0) {
  let existing = [];
  try { existing = JSON.parse(fs.readFileSync(errorsPath, 'utf8')); } catch (e) {}
  existing.push(...errors);
  fs.writeFileSync(errorsPath, JSON.stringify(existing, null, 2), 'utf8');
}
return item;

