  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function applyFix(text, fix) {
  const pattern = fix.regex
    ? new RegExp(fix.find, fix.flags || 'g')
    : new RegExp(escapeRegExp(fix.find), 'g');
  return text.replace(pattern, fix.replace);
}

